@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  List<List<int>> graph = [
    [0, 1, 1], 
    [1, 0, 1], 
    [1, 1, 0], 
  ];
  int n = graph.length;

  int inDegree[n] = List.filled(n, 0);
  List<int> topologicalSortResult = [];

  for (int i = 0; i < n; i++) {
    List<int> outgoing = graph[i];
    for (int j = 0; j < n; j++) {
      if (outgoing.contains(j)) {
        inDegree[j]++;
      }
    }
  }

  Queue<int> queue = Queue<int>();
  for (int i = 0; i < n; i++) {
    if (inDegree[i] == 0) {
      queue.add(i);
    }
  }

  while (queue.isNotEmpty) {
    int u = queue.removeFirst();
    topologicalSortResult.add(u);

    List<int> outgoing = graph[u];
    for (int v = 0; v < n; v++) {
      if (outgoing.contains(v)) {
        inDegree[v]--;
        if (inDegree[v] == 0) {
          queue.add(v);
        }
      }
    }
  }

  if (topologicalSortResult.isEmpty) {
    print("Graph contains a cycle, topological sort not possible.");
  } else {
    print("Topological Sort: ${topologicalSortResult.join(' -> ')}");
  }
}

