void dfs(List<List<int>> graph, List<bool> visited, List<int> disc, List<int> low, List<int> parent, int v, int time, List<int> stack) {
  visited[v] = true;
  disc[v] = low[v] = time++;
  stack.add(v);
  for (int u in graph[v]) {
    if (!visited[u]) {
      parent[u] = v;
      dfs(graph, visited, disc, low, parent, u, time, stack);
