  int lastColon = encoded.lastIndexOf(':');
  if (lastColon <= 0 || lastColon != encoded.length - 2) return <int>{};
  int i = 0;
  int total = 0;
  bool valid = true;
  while (i < lastColon) {
    String c = encoded[i];
    if (c.codeUnitAt(0) < 48 || c.codeUnitAt(0) > 57) { valid = false; break; }
    int digit = c.codeUnitAt(0) - 48;
    i++;
    if (i == lastColon) { valid = false; break; }
    int expected = encoded.codeUnitAt(i);
    if (expected < 33 || expected > 126) { valid = false; break; }
    int count = digit * 10 + (encoded.codeUnitAt(i + 1) - 48);
    for (int j = 0; j < count; j++) { total += c.codeUnitAt(0); }
    i += 2;
  }
  return <int>{total};
}

