List<String> _allSegmentations(String s, List<String> wordBreak) {
  List<List<String>> result = [];
  List<String> path = [];

  void backtrack(int start, int end) {
    if (start == end) {
      result.add(List.from(path)); 
      return;
    }

    for (int i = start; i <= end; i++) {
      if (wordBreak.contains(s.substring(start, i))) {
        path.add(s.substring(start, i));
        backtrack(i + 1, end);
        path.removeLast();
      }
    }
  }

  backtrack(0, s.length - 1);
  return result;
}

int _minWordLen(String s, Map<String, int> minWordLen) {
  if (!minWordLen.containsKey(s)) {
    return -1; 
  }
  int min = minWordLen[s]!;
  List<String> paths = _allSegmentations(s, wordBreak);
  for (var p in paths) {
    int len = p.length;
    if (len < min) {
      min = len;
    }
  }
  return min;
}

