bool wordBreak(String text, Map<String, List<int>> wordDict) {
  Set<String> wordSet = wordDict.keys.toSet();
  List<bool> dp = List.filled(text.length + 1, false);
  dp[0] = true; 

  for (int i = 1; i <= text.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && wordSet.contains(text.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }
  return dp[text.length];
}

List<String> wordBreak(String text, Map<String, List<int>> wordDict) {
  Set<String> wordSet = wordDict.keys.toSet();
  List<String> results = [];

  void search(int idx, String curr, List<String> path) {
    if (curr.length == text.length) {
      results.add(curr);
      return;
    }
    if (idx >= text.length) return; 

    for (int j = idx; j < text.length; j++) {
      if (wordSet.contains(text.substring(idx, j + 1))) {
        String newCurr = curr + ' ' + text.substring(idx, j + 1);
        search(j + 1, newCurr, path);
      }
    }
  }

  for (int i = 0; i <= text.length; i++) {
    if (dp[i] && wordSet.contains(text.substring(i))) {
      String newCurr = curr + ' ' + text.substring(i);
      search(i + 1, newCurr, []);
    }
  }
  return results;
}

int minLength(String word, Map<String, List<int>> wordDict) {
  Set<String> wordSet = wordDict.keys.toSet();
  List<int> dp = List.filled(word.length + 1, 0);

  for (int i = 1; i <= word.length; i++) {
    for (int j = 0; j < i; j++) {
      if (wordSet.contains(word.substring(j, i))) {
        dp[i] = dp[i] < dp[j] + 1 ? dp[i] : dp[j] + 1;
      }
    }
  }
  return dp[word.length];
}

