    'EXAMPLE',
    'EXAMPLE',
  ];

  int binarySearch(List<String> arr, String target) {
    int left = 0;
    int right = arr.length - 1;
    int result = -1;

    while (left <= right) {
      int mid = left + ((right - left) >> 1);
      if (arr[mid].compareTo(target) == 0) {
        result = mid;
        right = mid - 1;
      } else if (arr[mid].compareTo(target) < 0) {
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    }
    return result;
  }

  for (int i = 0; i < testStrings.length; i++) {
    String target = testStrings[i];
    int index = binarySearch(testStrings, target);
    if (index != -1) {
      print('Pattern found at positions: ${index + 1}');
    } else {
      print('Pattern not found.');
    }
  }
}

