void fn0() {

  List<String> _match(String text, String pattern) {
    if (pattern.isEmpty) {
      return [0];
    }

    int pLen = pattern.length;
    int tLen = text.length;
    List<int> dp = List.filled(tLen + 1, 0);

    for (int i = 1; i <= tLen; i++) {
      dp[i] = i;
    }

    for (int i = 0; i < pLen - 1; i++) {
      for (int j = 0; j < tLen; j++) {
        int match = 0;
        if (pattern[i] == text[j]) {
          match = 1;
        } else if (pattern[i + 1] == text[j]) {
          match = 2;
        } else {
          match = 3;
        }

        if (match == 0) {
          continue;
        }

        int k = dp[j];
        if (match == 1) {
          if (i == 0) {
            dp[j] = 1;
          } else if (pattern[i] == text[k]) {
            dp[j] = k + 1;
          } else {
            dp[j] = i + 1;
          }
        } else if (match == 2) {
          if (pattern[i + 1] == text[k]) {
            dp[j] = k + 2;
          } else {
            dp[j] = i + 2;
          }
        } else if (match == 3) {
          if (i >= 1) {
            dp[j] = dp[j - 1] + 1;
          } else {
            dp[j] = i + 1;
          }
        }
      }
    }

    List<int> positions = [];
    int i = 0;
    while (i <= tLen) {
      if (dp[i] > 1) {
        positions.add(i - 1);
        i += dp[i] - 1;
      } else {
        i++;
      }
    }

    return positions;
  }

  String text = "EXAMPLE";
  String pattern = "EXAMPLE";

  List<int> matches = _match(text, pattern);
  if (matches.isEmpty) {
    print("Pattern not found.");
  } else {
    print("Pattern found at positions: ${matches.join(' ')}");
  }
}

