List<List<String>> generateCombinations(List<String> items, int k) {

  List<List<String>> result = [];
  if (k <= 0 || k > items.length) {
    return result;
  }

  void backtrack(int index, List<String> current, List<String> remaining) {
    if (current.length == k) {
      result.add(List.from(current));
      return;
    }

    for (int i = index; i < items.length; i++) {
      String item = items[i];
      if (!current.contains(item)) {
        current.add(item);
        backtrack(i + 1, current, remaining);
        current.removeLast();
      }
    }
  }

  backtrack(0, [], items);
  return result;
}

