      _parent[x] = find(_parent[x]);
    }
    return _parent[x];
  }

  void unions(int x, int y) {
    final xRoot = find(x);
    final yRoot = find(y);

    if (xRoot == yRoot) return;

    if (_size[xRoot] < _size[yRoot]) {
      _parent[xRoot] = yRoot;
      _size[yRoot] += _size[xRoot];
    } else {
      _parent[yRoot] = xRoot;
