    }
    if (digitPattern.isEmpty) continue;
    if (seen.contains(digitPattern)) continue;
    seen.add(digitPattern);
    List<String> groups = digitPattern.split('-');
    List<String> parts = [];
    for (String group in groups) {
      List<String> runs = group.split(',');
      List<String> digits = [];
      for (String run in runs) {
        if (run.isNotEmpty) {
          int dashIdx = run.indexOf('-');
          if (dashIdx != -1) {
            String chunk = run.substring(0, dashIdx);
            digits.add(chunk);
          } else {
            digits.add(run);
          }
        }
      }
      parts.add(digits.isEmpty ? group : digits.sort().join('-'));
    }
    double score = 0.0;
    List<List<String>> grid = [];
    for (String part in parts) {
      List<String> rows = part.split('|');
      List<List<String>> segments = [];
      for (String row in rows) {
        List<String> cells = row.split(',');
        List<String> tokens = [];
        for (String cell in cells) {
          List<String> chunks = cell.split(':');
          String token = chunks[0];
          if (chunks.length > 1) {
            int count = int.parse(chunks[1]);
            for (int i = 0; i < count; i++) {
              token += chunks[1];
            }
          }
          tokens.add(token);
        }
        segments.add(tokens);
      }
      double width = 0.0;
      double height = 0.0;
      int minRows = segments.length;
      int maxRows = 0;
      int minCols = segments[0].length;
      int maxCols = 0;
      for (int i = 0; i < segments.length; i++) {
        for (int j = 0; j < segments[i].length; j++) {
          if (i == 0 || i == segments.length - 1 || j == 0 || j == segments[i].length - 1) {
            width += 1.0;
          }
          for (int k = 0; k < segments[i].length && j < segments[i].length; k++) {
            if (k != j) {
              height += 1.0;
            }
          }
          if (segments[i][j] == segments[i][j + 1] || segments[i + 1][j] == segments[i][j]) {
            score += 0.5;
          }
          if (segments[i][j] == segments[i][j - 1] || segments[i + 1][j] == segments[i][j]) {
            score -= 0.5;
          }
          if (i > 0 && segments[i - 1][j] == segments[i][j]) {
            score += 0.25;
          }
          if (i < segments.length - 1 && segments[i + 1][j] == segments[i][j]) {
            score -= 0.25;
          }
          if (j > 0 && segments[i][j] == segments[i][j - 1] && segments[i + 1][j] == segments[i][j]) {
            score += 1.0;
          }
          if (segments[i][j] == '.') {
            width += 1.0;
          } else if (segments[i][j] == '-') {
            height += 1.0;
          }
          if (segments[i][j] == '|' && i > 0 && j > 0 && j < segments[i - 1].length) {
            score += 0.5;
          }
          if (segments[i][j] == '|' && i > 0 && j < segments[i - 1].length) {
            score += 0.25;
          }
          if (segments[i][j] == '|' && j < segments[i + 1].length) {
            score -= 0.25;
          }
          if (segments[i][j] == '|' && i < segments.length - 1) {
            score -= 0.5;
          }
          for (int k = 0; k < segments[i].length && k < segments[i + 1].length; k++) {
            if (segments[i][j + k] == segments[i + 1][j + k]) {
              score += 0.25;
            }
          }
        }
      }
      grid.add([width, height, minRows, maxRows, minCols, maxCols]);
    }
    double area = 0.0;
    int minArea = 0x7FFFFFFFFFFFFFFF;
    for (List<double> cell in grid) {
      double w = cell[0];
      double h = cell[1];
      int minR = cell[2];
      int maxR = cell[3];
      int minC = cell[4];
      int maxC = cell[5];
      if (w == 0 || h == 0 || minR >= maxR || minC >= maxC) continue;
      double rectArea = w * h;
      double rotArea = w * maxR - (maxR - minR) * maxC - (maxC - minC) * minR + minR * minC;
      if (rotArea > rectArea) {
        rotArea = rectArea;
      }
      if (rotArea < minArea) {
        minArea = rotArea;
      }
      area += rotArea;
    }
    double density = area / (minArea + 1.0);
    if (density < 0.0) density = 0.0;
    result.add(code + '|' + (density == 0.0 ? '-' : '|' + (density > 0.5 ? '+' : '-' + ((density * 2.0).round() + 1))));
  }
  result.sort();
  return result;
}

