String fn0(String packetStream) {
  var seen = <String>{};
  var tagCount = <String, int>{};
  var invalid = <String>[];
  for (var i = 0; i < packetStream.length; i++) {
    var c = packetStream[i];
    if (c == '|') {
      if (seen.isEmpty) {
        invalid.add(packetStream.substring(0, i));
      }
      seen.clear();
      tagCount.clear();
      continue;
    }
    if (c != '<') {
      if (c == '|') {
        invalid.add(packetStream.substring(0, i));
      }
      continue;
    }
    var j = i + 1;
    var id = '';
    while (j < packetStream.length) {
      var code = packetStream.codeUnitAt(j);
      if (code < 48 || code > 57) {
        break;
      }
      id += packetStream[j];
      j++;
    }
    if (id.isEmpty) {
      invalid.add(packetStream.substring(0, i));
      continue;
    }
    var count = 0;
    j++;
    while (j < packetStream.length) {
      var code = packetStream.codeUnitAt(j);
      if (code < 48 || code > 57) {
        break;
      }
      count = count * 10 + (code - 48);
      j++;
    }
    if (count == 0) {
      invalid.add(packetStream.substring(0, i));
      continue;
    }
    var tag = id;
    if (count > 1) {
      tag += '$count';
    }
    if (seen.contains(tag)) {
      tagCount[tag] = (tagCount[tag] ?? 0) + count;
    } else {
      seen.add(tag);
      tagCount[tag] = count;
    }
  }
  if (seen.isEmpty) {
    return '';
  }
  var maxCount = 0;
  var bestTags = <String>[];
  for (var tag in seen) {
    var count = tagCount[tag]!;
    if (count > maxCount || (count == maxCount && tag < bestTags[0])) {
      maxCount = count;
      bestTags = [tag];
    } else if (count == maxCount) {
      bestTags.add(tag);
    }
  }
  bestTags.sort();
  var result = packetStream.substring(0);
  for (var tag in bestTags) {
    result += '$tag:${tagCount[tag]}|';
  }
  result += packetStream.substring(packetStream.length - 1);
  return result;
}

