  for (int i = 0; i < code.length; i++) {
    String sq = '${code[i]}';
    if (sq.length != 2) continue;
    if (i > 0 && code[i] == code[i - 1]) continue;
    if (sq[0].codeUnitAt(0) < 97 || sq[0].codeUnitAt(0) > 104) continue;
    if (sq[1].codeUnitAt(0) < 49 || sq[1].codeUnitAt(0) > 56) continue;
    if (seen.contains(sq)) continue;
