    List<List<int>> dirs = [
      [2, 1], [2, -1], [-2, 1], [-2, -1],
      [1, 2], [1, -2], [-1, 2], [-1, -2]
    ];
    bool isEdge = (col == 0 || col == 7 || row == 0 || row == 7);
    bool isCorner = isEdge && (col == 1 || col == 6 || row == 1 || row == 6);
    bool isPair = (col == 2 || col == 5 || row == 2 || row == 5);
    bool hasNeighbor = false;
    double dist = 0.0;
    for (var d in dirs) {
      int nc = col + d[0];
      int nr = row + d[1];
      if (nc >= 0 && nc <= 7 && nr >= 0 && nr <= 7) {
        hasNeighbor = true;
        break;
      }
    }
    if (hasNeighbor) {
      dist = (col - 2.0) * (col - 2.0) + (row - 2.0) * (row - 2.0);
    }
    squares.add('${sq[0]}${sq[1]}${isEdge ? 1 : 0}${isCorner ? 1 : 0}${isPair ? 1 : 0}${dist.toString().padLeft(3, '0')}');
  }
