List<String> fn0(String dna) {
  if (dna.isEmpty) return [];

  List<String> results = [];
  Set<String> seen = {};

  Set<String> visited = {};

  List<int> stack = [];

  for (int i = 0; i < dna.length; i++) {
    String base = dna[i];

    String state = '0';
    if (base == 'A') state = '1';
    if (base == 'T') state = '2';
    if (base == 'C') state = '3';
    if (base == 'G') state = '4';

    if (state == '0') continue;

    bool allowFlip = (state == '1' && base == 'T') ||
        (state == '2' && base == 'A') ||
        (state == '3' && base == 'C') ||
        (state == '4' && base == 'G');

    if (!allowFlip) continue;

    String key = '$base$state';
    if (seen.contains(key)) continue;
    seen.add(key);

    if (stack.isNotEmpty && stack.last == state) {
      results.add(stack.removeLast());
    } else {
      stack.add(state);
    }

    visited.add(key);

    String nextState = '';
    if (state == '1') nextState = '2';
    if (state == '2') nextState = '3';
    if (state == '3') nextState = '4';
    if (state == '4') nextState = '1';

    if (nextState.isNotEmpty) {
      String nextKey = '$base$nextState';
      if (!visited.contains(nextKey)) {
        visited.add(nextKey);
        stack.add(nextState);
      }
    }
  }

  List<String> sorted = List<String>.from(stack);
  sorted.sort();

  for (String result in sorted) {
    results.add(result);
  }

  return results;
}

