class Quaternion {
  final double x, y, z, w;
  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion operator +(Quaternion other) {
    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator *(double scalar) {
    return Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);
  }

  Quaternion operator *(Quaternion other) {
    double xx = x * other.x, xy = x * other.y, xz = x * other.z, xw = x * other.w;
    double yy = y * other.y, yz = y * other.z, yw = y * other.w;
    double zz = z * other.z, zw = z * other.w;
    return Quaternion(xx - yy - zz + w * w, xy + yz + zw, xz + yz - xw * w, xw + yw + zz * w);
  }

  Quaternion operator ^(int n) {
    Quaternion temp = this;
    for (int i = 0; i < n; i++) {
      temp = temp * temp;
    }
    return temp;
  }

  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  double norm() {
    return x * x + y * y + z * z + w * w;
  }

  Quaternion normalized() {
    return this * Quaternion(1 / norm(), 0, 0, 0);
  }

  double distance(Quaternion other) {
    Quaternion diff = other - *this;
    return diff.x * diff.x + diff.y * diff.y + diff.z * diff.z;
  }

  @override
  String toString() {
    return 'q1 = $x + $y * i + $z * j + $w * k';
  }
}

class QuaternionMatrix {
  List<List<double>> matrix = List.generate(4, (_) => List.filled(4, 0));

  void set(int row, int col, double value) {
    matrix[row][col] = value;
  }

  double get(int row, int col) {
    return matrix[row][col];
  }

  QuaternionMatrix operator *(Quaternion quaternion) {
    QuaternionMatrix result = QuaternionMatrix();
    for (int r = 0; r < 4; r++) {
      for (int c = 0; c < 4; c++) {
        double sum = 0;
        for (int k = 0; k < 4; k++) {
          sum += get(r, k) * quaternion.matrix[k][c];
        }
        result.set(r, c, sum);
      }
    }
    return result;
  }

  @override
  String toString() {
    String s = '';
    for (int r = 0; r < 4; r++) {
      for (int c = 0; c < 4; c++) {
        s += get(r, c).toString() + ' ';
      }
      if (r < 3) s += '\n';
    }
    return s;
  }
}

