class Quaternion {
  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.unit =>
      const Quaternion(0.0, 0.0, 0.0, 1.0);

  const Quaternion.zero =>
      const Quaternion(0.0, 0.0, 0.0, 0.0);

  const Quaternion.fromList(List<double> list)
      : x = list[0],
        y = list[1],
        z = list[2],
        w = list[3];

  const Quaternion.random()
      : x = (2 * (Math.pi * (Math.random() * 2))).cos(),
        y = (2 * (Math.pi * (Math.random() * 2))).cos(),
        z = (2 * (Math.pi * (Math.random() * 2))).cos(),
        w = 1.0;

  const Quaternion.lookAt(Vector3 from, Vector3 to)
      : x = (to.x - from.x).abs(),
        y = (to.y - from.y).abs(),
        z = (to.z - from.z).abs(),
        w = to.dot(from);

  double norm() => x * x + y * y + z * z + w * w;

  Quaternion conjugate() =>
      const Quaternion(x, y, -z, w);

  Quaternion inverse() =>
      const Quaternion(x, y, z, 1.0 / (x * x + y * y + z * z + w * w));

  Quaternion rotate(Quaternion axis, double angle) {
    final q = axis * angle;
    return const Quaternion(x + q.x * w * 2, y + q.y * w * 2, z + q.z * w * 2, w * (1.0 - q.x * q.x - q.y * q.y - q.z * q.z));
  }

  double dot(Quaternion q) => x * q.x + y * q.y + z * q.z + w * q.w;

  @override
  String toString() => '($x, $y, $z, $w)';
}

class Vector3 {
  final double x, y, z;

  Vector3(this.x, this.y, this.z);

  Vector3.zero => const Vector3(0.0, 0.0, 0.0);

  Vector3.unit => const Vector3(0.0, 0.0, 0.0);

  Vector3.random()
      : x = (2 * (Math.pi * (Math.random() * 2))).cos(),
        y = (2 * (Math.pi * (Math.random() * 2))).cos(),
        z = (2 * (Math.pi * (Math.random() * 2))).cos();

  @override
  String toString() => '($x, $y, $z)';

  Vector3 operator +(Vector3 q) => const Vector3(x + q.x, y + q.y, z + q.z);

  Vector3 operator -(Vector3 q) => const Vector3(x - q.x, y - q.y, z - q.z);

  Vector3 operator *(double s) => const Vector3(s * x, s * y, s * z);

  double dot(Vector3 q) => x * q.x + y * q.y + z * q.z;

  double cross(Vector3 q) => x * q.y - y * q.x,
      z * q.x - x * q.z,
      y * q.z - z * q.y;

  double abs() => x * x + y * y + z * z;

  Vector3 normalize() {
    final inv = 1.0 / abs();
    return const Vector3(x * inv, y * inv, z * inv);
  }
}

