class Quaternion {
  final double real;
  final double imaginary1;
  final double imaginary2;
  final double imaginary3;

  const Quaternion(this.real, [this.imaginary1 = 0.0, this.imaginary2 = 0.0, this.imaginary3 = 0.0]);

  const Quaternion.unit => const Quaternion(0.0, 1.0, 0.0, 0.0);
  const Quaternion.zero => const Quaternion(0.0, 0.0, 0.0, 0.0);

  const Quaternion.random => const Quaternion(
    random.nextDouble() * 2 - 1,
    random.nextDouble() * 2 - 1,
    random.nextDouble() * 2 - 1,
    random.nextDouble() * 2 - 1,
  );

  const Quaternion.identity => const Quaternion.unit;

  const Quaternion.inverse(this) => const Quaternion(real, -imaginary1, -imaginary2, -imaginary3);

  const Quaternion operator +(this) => const Quaternion(real, imaginary1, imaginary2, imaginary3);

  const Quaternion operator -(this) => const Quaternion(real, -imaginary1, -imaginary2, -imaginary3);

  const Quaternion operator *(this) => const Quaternion(real * 2 - imaginary1 * imaginary2 - imaginary3 * imaginary1, imaginary1 * imaginary3 - imaginary2 * imaginary3, imaginary1 * imaginary2, imaginary2 * imaginary3);

  const Quaternion conjugate() => const Quaternion(real, -imaginary1, -imaginary2, -imaginary3);

  const Quaternion normalized() {
    final norm = sqrt(real * real + imaginary1 * imaginary1 + imaginary2 * imaginary2 + imaginary3 * imaginary3);
    return const Quaternion(real / norm, imaginary1 / norm, imaginary2 / norm, imaginary3 / norm);
  }

  const Quaternion rotate(double angle, const Quaternion axis) {
    const cos = cos(angle);
    const sin = sin(angle);
    return const Quaternion(
      real * cos - imaginary1 * sin * axis.imaginary1 - imaginary2 * sin * axis.imaginary2 - imaginary3 * sin * axis.imaginary3,
      real * sin * axis.imaginary1 + imaginary1 * cos - imaginary2 * sin * axis.imaginary2 - imaginary3 * sin * axis.imaginary3,
      real * sin * axis.imaginary2 + imaginary2 * sin - imaginary1 * cos - imaginary3 * sin * axis.imaginary3,
      real * sin * axis.imaginary3 + imaginary3 * sin - imaginary1 * cos - imaginary2 * sin * axis.imaginary2,
    );
  }

  @override
  String toString() =>
      'q1 = $real + $imaginary1 * i + $imaginary2 * j + $imaginary3 * k';
}

