      (p[0] * cosTheta + p[2] * sinTheta) * cosTheta - (p[1] * sinTheta),
      (p[0] * sinTheta + p[2] * cosTheta) * cosTheta + (p[1] * sinTheta),
      p[3],
      p[3],
    );
  }

  Quaternion operator *(Quaternion other) {
    return Quaternion(
      x * other.w - y * other.z - z * other.y + w * other.x,
      y * other.w + x * other.z + z * other.y + w * other.x,
      z * other.w - y * other.x + x * other.z + w * other.y,
      w * other.w + x * other.x + y * other.y + z * other.z,
