      const Quaternion(x * other.x - y * other.y - z * other.z - w * other.w,
          x * other.y + y * other.x - z * other.w - w * other.z,
          x * other.z + y * other.w - z * other.x - w * other.y,
          x * other.w + y * other.z + z * other.x - w * other.y);

