class Quaternion {
  double x, y, z, w;
  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion operator +(Quaternion other) {
    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator *(Quaternion other) {
    double nx = x * other.w - y * other.z - z * other.y - w * other.x;
    double ny = x * other.z + y * other.w - z * other.x - w * other.y;
    double nz = x * other.y + y * other.z + z * other.x - w * other.w;
    double nw = x * other.w * other.w + y * other.z * other.w + z * other.y * other.w + w * other.x * other.w;
    return Quaternion(nx, ny, nz, nw);
  }

  Quaternion operator *=(Quaternion other) {
    x = x * other.w - y * other.z - z * other.y - w * other.x;
    y = x * other.z + y * other.w - z * other.x - w * other.y;
    z = x * other.y + y * other.z + z * other.x - w * other.w;
    w = x * other.w * other.w + y * other.z * other.w + z * other.y * other.w + w * other.x * other.w;
    return this;
  }

  Quaternion operator /(Quaternion other) {
    double denom = other.w * other.w + other.z * other.z + other.y * other.y;
    if (denom == 0) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    double inv = 1 / denom;
    return Quaternion(
      (x * other.w + y * other.z + z * other.y) * inv,
      (y * other.w - x * other.z - z * other.y) * inv,
      (z * other.w - y * other.x - x * other.z) * inv,
      (x * other.w * other.w + y * other.z * other.w + z * other.y * other.w + w * other.x * other.w) * inv,
    );
  }

  Quaternion operator -() {
    return Quaternion(-x, -y, -z, -w);
  }

  Quaternion get conjugate => Quaternion(x, y, z, -w);

  double norm() {
    return sqrt(x * x + y * y + z * z + w * w);
  }

  void rotateBy(Quaternion axis, double angle) {
    double cos = cos(angle);
    double sin = sin(angle);
    double nx = axis.x * sin + axis.z * cos;
    double ny = axis.y * sin + axis.z * -cos;
    double nz = axis.z * sin - axis.y * cos;
    x = cos * x + nx * sin;
    y = cos * y + ny * sin;
    z = cos * z + nz * sin;
    w = cos * w + (nx * y - ny * x) * sin;
  }
}

