      }
    }
  }

  Set<int> result = {};
  for (int i = 1; i <= n; i++) {
    for (int j = 0; j <= m; j++) {
      if (dp[i][j]) {
        result.add(arrivalDays[i - 1]);
        break;
      }
    }
  }
  return result;
}

