  List<List<double>> history = [];
  for (String line in logLines) {
    if (line.isEmpty) {
      stack.clear();
      history.add([]);
      continue;
    }
    int colonIndex = line.indexOf(':');
    if (colonIndex == -1) {
      stack.clear();
      history.add([]);
      continue;
    }
    String level = line[0];
    String body = line.substring(1, colonIndex);
    List<String> parts = body.split(' ');
    double? prev = stack.isEmpty ? null : stack.last;
    double total = 0.0;
    for (String part in parts) {
      if (part.isEmpty) {
        total += (prev ?? 0.0).toDouble();
        continue;
      }
      String kind = part[0];
      if (kind == 'S' || kind == 'R') {
        total += (prev ?? 0.0) + (kind == 'S' ? 2.0 : 1.0).toDouble();
      } else if (kind == 'B' || kind == 'M' || kind == 'D' || kind == 'C') {
        total += (prev ?? 0.0) - (kind == 'B' ? 2.0 : 1.0).toDouble();
      } else if (kind == 'P') {
        total += (prev ?? 0.0).toDouble();
      }
      if (prev != null) {
        stack.add(prev);
      }
      prev = total;
    }
    history.add(List<double>.from(stack));
    if (level == 'S') {
      stack.clear();
    } else if (level == 'P' && total > 0.0) {
      stack.add(total);
    }
  }
  return stack.isEmpty ? 0.0 : stack.last;
}

