  if (rows == 0) return {};
  int cols = grid[0].length;
  List<List<int>> dp = List.generate(rows, (_) => List<int>.filled(cols, 0));
  Map<String, int> totals = {};

  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      int maxLen = 0;
      int bestStart = -1;
      int count = 0;

      for (int len = 1; len <= 3; len++) {
        for (int start = 0; start + len <= cols; start++) {
          bool allSame = true;
          for (int k = 0; k < len; k++) {
            int val = grid[i][start + k];
            if (val != grid[i][j]) {
              allSame = false;
              break;
            }
          }
          if (allSame) {
            if (len > maxLen) {
              maxLen = len;
              bestStart = start;
            } else if (len == maxLen && len > 0 && start < bestStart) {
              bestStart = start;
            }
          }
        }
      }

      dp[i][j] = maxLen;
      totals[grid[i][j]] = (totals[grid[i][j]] ?? 0) + count;
    }
