      if (stack.isEmpty) return 'INVALID';
      String last = stack.removeLast();
      if (last == 'D:') {
        stack.add('C:');
      } else if (last == 'C:') {
        stack.add('FINAL:');
      } else {
        return 'INVALID';
      }
    } else if (token == 'D:') {
      if (stack.isEmpty) return 'INVALID';
      String top = stack.removeLast();
      if (top == 'C:') {
        stack.add('D:');
      } else if (top == 'FINAL:') {
        stack.add('OPEN');
      } else {
        return 'INVALID';
      }
    } else if (token == 'C:') {
      if (stack.isEmpty) return 'INVALID';
      String top = stack.removeLast();
      if (top == 'D:') {
        stack.add('C:');
      } else if (top == 'FINAL:') {
        stack.add('OPEN');
      } else {
        return 'INVALID';
      }
    } else if (token == 'FINAL:') {
      if (stack.isEmpty) return 'INVALID';
      String top = stack.removeLast();
      if (top == 'OPEN') {
        return 'FINAL:net=${stack.length},result=OPEN';
      } else {
        return 'INVALID';
      }
    } else {
      return 'INVALID';
    }
  }
  return 'INVALID';
}

