@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(List<String> commands) {
  List<String> log = [];
  List<int> net = [];
  int total = 0;
  for (String cmd in commands) {
    if (cmd == 'OPEN') {
      log.add('OPEN');
      net.add(0);
    } else if (cmd == 'CLOSE') {
      if (log.isNotEmpty) {
        String last = log.removeLast();
        if (last == 'OPEN') {
          net[net.length - 1] = 0;
        } else if (last == 'D:') {
          net.removeLast();
        } else if (last == 'C:') {
          int c = net.removeLast();
          total += c;
          net.add(c);
        }
      }
    } else if (cmd.startsWith('D:')) {
      int count = int.parse(cmd.substring(1));
      if (net.isNotEmpty) {
        int previous = net.removeLast();
        for (int i = 0; i < count; i++) {
          total -= previous;
        }
        net.add(previous);
      }
    } else if (cmd.startsWith('C:')) {
      int count = int.parse(cmd.substring(1));
      if (net.isNotEmpty) {
        int previous = net.removeLast();
        for (int i = 0; i < count; i++) {
          total += previous;
        }
        net.add(previous);
      }
    } else if (cmd == 'FINAL:') {
      if (net.isNotEmpty) {
        total -= net.removeLast();
      }
      log.add('FINAL:$total,result=${total >= 0 ? "APPROVED" : "REJECTED"}');
    }
  }
  return log;
}

