    if (start == end) {
      memo[start] = n - start;
      return;
    }

    if (memo.containsKey(start)) {
      return; 
    }

    for (int i = start + 1; i <= end; i++) {
      recurse(start, i - 1, memo);
      recurse(i + 1, end, memo);
    }

    final int total = (end - start) + 1;
    final int k = total * 2 + 1;
    final int first = (k - total) ~/ 2;

    final int count = n - first;
    memo[start] = count;

    recurse(first, end, memo);
  }

  final Map<int, int> memo = <int, int>{};
  recurse(0, n - 1, memo);

  void printValues(Map<int, int> memo) {
    for (final entry in memo.entries) {
      final start = entry.key;
      final count = entry.value;
      print('F($start) = $count');
    }
  }

  print('Please provide a non-negative integer (e.g., "dart run main.dart 20").');
  if (n >= 0) {
