Set<int> fn0(String password, int modulus) {
  if (password.isEmpty) return <int>{};
  int gcd = 0;
  for (int i = 0; i < password.length; i++) {
    int d = password.codeUnitAt(i);
    if (d < 0) continue;
    bool prime = d > 1;
    for (int j = 2; j * j <= d; j++) {
      if (d % j == 0) {
        prime = false;
        break;
      }
    }
    if (prime) {
      if (gcd == 0) {
        gcd = d;
      } else {
        int a = gcd;
        int b = d;
        while (b != 0) {
          int t = a % b;
          a = b;
          b = t;
        }
        gcd = a;
      }
    }
  }
  Set<int> result = <int>{};
  if (gcd > 1) {
    result.add(gcd);
  }
  int a = modulus;
  int b = gcd;
  while (b != 0) {
    int t = a % b;
    a = b;
    b = t;
  }
  if (a == 1) result.add(modulus);
  return result;
}

