  for (int i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + counts[i] - counts[i] * (i > 0 ? counts[i - 1] : 0);
  }

  int bestIdx = 0;
  int currentMax = 0;

  for (int i = 1; i <= n; i++) {
    if (prefix[i] > currentMax) {
      currentMax = prefix[i];
      bestIdx = i;
    }
  }

  return bestIdx;
}

