int fn0(List<List<int>> grid, int minLength) {
  if (grid.isEmpty || grid[0].isEmpty) return 0;
  int rows = grid.length;
  int cols = grid[0].length;
  List<List<int>> dp = List.generate(rows, (_) => List.filled(cols, 0));
  for (int c = 0; c < cols; c++) {
    dp[0][c] = grid[0][c];
  }
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      int minVal = dp[r][c];
      for (int p = c - 1; p >= 0; p--) {
        if (grid[r][p] < minVal) minVal = grid[r][p];
      }
      if (c > 0) {
        dp[r][c] = minVal + grid[r][c] - grid[r][c - 1];
      } else {
        dp[r][c] = minVal + grid[r][c];
      }
      if (r > 0) {
        for (int prevC = c - 1; prevC >= 0; prevC--) {
          if (dp[r - 1][prevC] > dp[r][c] && grid[r][c] > grid[r - 1][prevC]) {
            dp[r][c] = dp[r - 1][prevC] + grid[r][c];
          }
        }
      }
      if (dp[r][c] < 0) dp[r][c] = 0;
    }
  }
  int best = dp[0][0];
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (dp[r][c] > best) best = dp[r][c];
    }
  }
  return best >= minLength ? best : 0;
}

