    int userMask = _getRoleBitfield(user);
    int resourceMask = _getRoleBitfield(resource);
    int actionMask = _getRoleBitfield(action);
    int roleMask = _getRoleBitfield(role);

    int sharedMask = ((resourceMask & actionMask) | (userMask & actionMask)) & (~roleMask);
    int sharedBits = sharedMask & 0x7FFFFFFFFFFFFFFF;

    if (sharedBits == 0) {
