bool auth(String role, String action) {
  var parts = role.split('!');
  var baseRole = parts[0];
  var resourcePermissions = permissions[baseRole]!;
  var hasPermission = resourcePermissions.containsKey(action);
  return hasPermission && resourcePermissions[action]! > 0;
}

