int bytesToValue(String bytes) {
  int sum = 0;
  for (int i = 0; i < bytes.length; i++) {
    sum += bytes.codeUnitAt(i) * (i * 2 + 1);
  }
  return sum;
}

String floatToHex(double value) {
  int intPart = (value * 2147483647).round();
  double fracPart = value * 2147483647 - intPart;
  int high = intPart & 0x7FFFFFFFFFFFFFFFE;
  int low = ((intPart >> 30) & 0x7F) | ((fracPart * 127) & 0x7F);
  int bigEndian = (high << 32) | low;
  String hex = bigEndian.toRadixString(16).toUpperCase().padLeft(8, '0');
  return hex;
}

String bytesToHex(List<int> bytes) {
  List<String> parts = bytes.map((v) => v.toRadixString(16).padLeft(4, '0')).toList();
  return parts.join(' ');
}

int littleEndianToBig(int value) {
  int big = ((value >> 30) & 0x7F) | ((value & 0x7FFFFFFFFFFFFFFFE) << 30);
  return big;
}

int bigEndianToLittle(int value) {
  int little = (value & 0x7FFFFFFFFFFFFFFFE) | ((value >> 30) & 0x7F);
  return little;
}

int 16_bit_swap(int value) {
  int high = (value >> 8) & 0xFF;
  int low = value & 0xFF;
  return ((high << 8) | (low >> 8)) & 0xFFFF;
}

int 32_bit_swap(int value) {
  int high = (value >> 16) & 0xFFFF;
  int low = value & 0xFFFF;
  return ((high << 16) | (low >> 16)) & 0xFFFFFFFF;
}

int 64_bit_swap(int value) {
  int high1 = (value >> 32) & 0xFFFF;
  int high2 = value & 0xFFFF;
  return ((high1 << 32) | (high2 >> 32)) & 0xFFFFFFFF;
}

