  List<List<int>> itemSets = frequentItemsets.map((s) => s.toList()).toList();

  Map<int, List<int>> associationRules = {};
  for (var itemset in itemSets) {
    for (int i = 2; i <= maxItems; i++) {
      if (itemset.length == i) {
        continue;
      }

      Map<int, int> support = {};
      for (var t in transactions) {
        bool allSub = true;
        for (var item in itemset) {
          if (!t.contains(item)) {
            allSub = false;
            break;
          }
        }
        if (allSub) {
          support[itemset] = (support[itemset] ?? 0) + 1;
        }
      }

      int minSupport = minSupport * maxItems;
      if (support[itemset]! >= minSupport) {
        associationRules[itemset] = [];
      }
    }
  }

  List<MapEntry<Set<int>, double>> rules = [];
  for (var itemset in associationRules.entries) {
    int support = itemset.value;
    if (support < minSupport) {
      continue;
    }

    Map<int, int> confidence = {};
    for (var item in itemset.key) {
      confidence[item] = (confidence[item] ?? 0) + support;
    }

    double minConfidence = minConfidence * support;
    if (confidence.values.isNotEmpty && confidence.values.first >= minConfidence) {
      rules.add(MapEntry(itemset.key, confidence.values.first / support));
    }
  }

  rules.sort((a, b) => a.value.compareTo(b.value));

  print('Frequent Itemsets:');
  print(frequentItemsets);

  print('\nAssociation Rules:');
  for (var rule in rules) {
    print('${rule.key} (support: ${rule.value}, confidence: ${rule.key[0]}');
  }
}

