void fn0() {

  final items = {
    'Milk',
    'Bread',
    'Butter',
    'Milk and Bread',
    'Milk and Butter',
    'Bread and Butter',
    'Milk and Bread and Butter',
  };

  final transactions = <Set<String>>[
    {'Milk', 'Bread'},
    {'Milk', 'Butter'},
    {'Bread', 'Butter'},
    {'Milk', 'Bread', 'Butter'},
  ];

  final minSupport = 2 / 3;
  final minConfidence = 0.7;

  int countOf(Set<String> item) {
    int count = 0;
    for (var trans in transactions) {
      if (trans.contains(item)) {
        count++;
      }
    }
    return count;
  }

  void generateFrequentItemsets(Set<String> current, Map<Set<String>, int> freq, Set<Set<String>> frequent) {
    if (current.length == 1) {
      freq[current] = countOf(current);
      if (freq[current]! >= minSupport) {
        frequent.add(current);
      }
      return;
    }

    for (int i = 1; i < current.length; i++) {
      for (int j = 0; j <= current.length - i; j++) {
        Set<String> prefix = current.subset(0, j);
        Set<String> suffix = current.subset(j);

        if (freq[prefix]! >= minSupport) {
          generateFrequentItemsets(suffix, freq, frequent);
        }
      }
    }
  }

  final Map<Set<String>, int> freq = <Set<String>, int>{};
  final Set<Set<String>> frequent = <Set<String>>{};
  generateFrequentItemsets(items, freq, frequent);

  print('Frequent Itemsets:');
  print(frequent.toList()..sort());

  final Map<Set<String>, Set<String>> associationRules = <Set<String>, Set<String>>{};
  for (var itemset in frequent) {
    for (int i = 1; i < itemset.length; i++) {
      Set<String> left = itemset.subset(0, i);
      Set<String> right = itemset.subset(i);

      if (freq[left]! >= minSupport) {
        double conf = freq[right]! / freq[left]!;
        if (conf >= minConfidence) {
          associationRules[left] = right;
        }
      }
    }
  }

  print('\nAssociation Rules:');
  for (var entry in associationRules.entries) {
    print('${entry.key} => ${entry.value} (support: ${freq[entry.key]}, confidence: ${entry.value / freq[entry.key]})');
  }
}

