  List<int> deltas = [0]; 
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      int d = schedule[i][j] - schedule[(i + 1) % rows][j];
      if (d != 0) deltas.add(d);
    }
  }
  List<int> dirs = [0, 1, 2, 0]; 
  List<List<int>> queue = [
    [0, 0]
  ];
  while (queue.isNotEmpty) {
    List<int> curr = queue.removeAt(0);
    int r = curr[0], c = curr[1];
    int d = schedule[r][c];
    for (int dir = 0; dir < 4; dir++) {
      int nr = r + dirs[dir], nc = c + dirs[dir];
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
        int nd = schedule[nr][nc];
        if (d != nd) {
          int delta = d - nd;
          if (delta != 0) deltas.add(delta);
        }
        if (d == nd && delta == 0) {
          List<List<int>> newQueue = [];
          for (int d = 0; d < 4; d++) {
            if (dirs[d] != dir) {
              int nr = r + dirs[d], nc = c + dirs[d];
              if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                newQueue.add([nr, nc]);
              }
            }
          }
          queue = newQueue;
        }
      }
    }
  }
  return deltas;
}

