bool fn0(List<int> barcodeDigits, List<int> weights, int drift) {
  int n = barcodeDigits.length;
  if (weights.isEmpty) return false;
  if (n != weights.length) return false;
  if (n < 2) return true;
  List<List<int>> dp = List.generate(n, (_) => List.filled(n, 0));
  for (int i = 0; i < n; i++) {
    dp[i][i] = barcodeDigits[i] * weights[i] - drift;
  }
  for (int len = 2; len <= n; len++) {
    for (int start = 0; start <= n - len; start++) {
      int end = start + len - 1;
      for (int split = start + 1; split <= end; split++) {
        dp[start][end] += dp[start][split] + dp[split][end];
      }
    }
  }
  return dp[0][n - 1] == 0;
}

