    width: random.nextDouble() * 200 - 100,
    height: random.nextDouble() * 200 - 100,
    x: random.nextDouble() * 400 - 200,
    y: random.nextDouble() * 400 - 200,
  );

  const Rectangle.unitCircle() : this(
    width: sqrt(random.nextDouble()),
    height: sqrt(random.nextDouble()),
  );

  Rectangle.circle(double radius)
      : this(
          radius * 2,
          radius * 2,
          x: -radius,
          y: -radius,
        );

  Rectangle.circlePoint(Point point) : this(
        point.x * 2,
        point.y * 2,
        x: point.x - point.x * 2,
        y: point.y - point.y * 2,
      );

  Rectangle.ellipse(double a, double b, double cx, double cy) : this(
        a * 2,
        b * 2,
        x: cx - a * 2,
        y: cy - b * 2,
      );

  Rectangle.triangle(Point p1, Point p2, Point p3) {
    const d = 100;
    double minX = p1.x < p2.x ? p1.x : p2.x;
    double maxX = p1.x > p2.x ? p1.x : p2.x;
    double minY = p1.y < p2.y ? p1.y : p2.y;
    double maxY = p1.y > p2.y ? p1.y : p2.y;
    this(
      (maxX - minX) > d ? (maxX - minX) : d,
      (maxY - minY) > d ? (maxY - minY) : d,
      x: minX,
      y: minY,
    );
  }

  Rectangle.fromPoints(Point p1, Point p2) : this(
        ((p2.x - p1.x).abs() > (p2.y - p1.y).abs()
            ? p2.x - p1.x
            : p2.y - p1.y) * 2,
        ((p2.x - p1.x).abs() > (p2.y - p1.y).abs()
            ? p2.y - p1.y
            : p2.x - p1.x),
        x: p1.x,
        y: p1.y,
      );

  Rectangle.fromPointsEven(Point p1, Point p2) : this(
        ((p2.x - p1.x).abs() > (p2.y - p1.y).abs()
            ? p2.x - p1.x
            : p2.y - p1.y) * 2,
        ((p2.x - p1.x).abs() > (p2.y - p1.y).abs()
            ? p2.y - p1.y
            : p2.x - p1.x),
        x: p1.x,
        y: p1.y,
      );

  @override
  String toString() => 'Rectangle(center: ($x, $y), halfWidth: $width, halfHeight: $height)';
}

