    }
    return clusters[i] = find(clusters[i]);
  }

  void union(int x, int y) {
    var rootX = find(x);
    var rootY = find(y);
    if (rootX != rootY) {
      if (rootX < rootY) {
        clusters[rootX] = rootY;
      } else {
        clusters[rootY] = rootX;
