  final int n = data.length;

  final visited = List.filled(n, false);
  final queue = List<int>.generate(n, (i) => i);

  for (int i = 0; i < minPts; i++) {
    visited[queue.removeAt(0)] = true;
  }

  final int clusterId = List.filled(n, 0);
  int centroidCount = 0;

  for (int iter = 0; iter < maxIterations && centroidCount < k; iter++) {

    final indices = <int>[];
    for (int i = 0; i < n; i++) {
      if (visited[i]) {
        indices.add(i);
      }
    }

    if (indices.isEmpty) {
      break;
    }

    final centroids = <int>[];

    for (final int i in indices) {
      for (int j = 0; j < data[i].length; j++) {
        centroids.add(data[i][j]);
      }
    }

    centroids.sort();

    final clusterIdList = List.filled(n, 0);
    int currentClusterId = 0;

    for (final double center in centroids) {
      final int rank = center * (n + 1);

      for (int i = 0; i < n; i++) {
        if (data[i].length == 2 && data[i][0] == center) {
          clusterIdList[i] = rank;
        }
      }

      currentClusterId++;
    }

    for (int i = 0; i < n; i++) {
      if (clusterIdList[i] != 0) {
        clusterId[i] = clusterIdList[i];
      }
    }

