      for (int i = 0; i < n; i++) {
        if (clusterId[i] == j + 1) {
          count++;
          sumX += data[i][0];
          sumY += data[i][1];
        }
      }

      if (count >= minPts) {
        newCentroids.add(sumX / count);
        newCentroids.add(sumY / count);
        newClusterIds.add(j + 1);
      }
    }

    clusterId = newClusterIds;
    centroids = newCentroids;
    centroidCount = k;
  }

  print('Cluster ${centroidCount} formed:');
  for (int i = 0; i < n; i++) {
    if (clusterId[i] > 0) {
      print('  Points: ${data[i]} -> Cluster ${clusterId[i]}');
    }
  }
