class Queue<T> {
  List<T> queue = [];
  void add(T item) {
    queue.add(item);
  }
  T removeFirst() {
    if (queue.isEmpty) return null;
    return queue.removeAt(0);
  }
}

class BreadthFirst {
  void traverse(TreeNode root) {
    Queue<TreeNode> queue = Queue<TreeNode>();
    if (root == null) return;
    queue.add(root);
    List<int> result = [];
    while (queue.isNotEmpty) {
      TreeNode current = queue.removeFirst();
      result.add(current.value);
      for (TreeNode child in current.children) {
        queue.add(child);
      }
    }
    print('Breadth-first traversal: $result');
  }
}

