bool fn0(List<String> schedule) {
  if (schedule.isEmpty) {
    return true;
  }

  List<List<int>> activeHours = [];
  List<int> transitions = [];

  for (String token in schedule) {
    List<String> parts = token.split(':');
    int start = int.parse(parts[0]);
    int duration = int.parse(parts[1]);

    if (duration <= 0) {
      return false;
    }

    List<int> segment = [start];
    activeHours.add(segment);

    for (int i = 1; i < duration; i++) {
      segment.add(start + i);
    }

    if (segment[0] < transitions.last) {
      transitions.add(segment[0]);
    }

    for (int hour in segment) {
      activeHours[0].add(hour);
    }
  }

  if (transitions.length < 2) {
    return false;
  }

  Map<int, int> prev = {};
  Map<int, int> curr = {};
  for (int hour = transitions[0]; hour <= transitions.last; hour++) {
    prev[hour] = 0;
    curr[hour] = 0;
  }

  for (List<int> seg in activeHours) {
    for (int hour in seg) {
      prev[hour] = curr[hour]!;
      curr[hour] = prev[hour]! + 1;
    }
  }

  return true;
}

