List<int> fn0(List<String> mazeRow, int maxPasses, Map<String, int> itemCounts) {
  List<int> passes = [];
  int row = 0;
  bool foundItem = false;

  while (row < mazeRow.length) {
    String cell = mazeRow[row];
    if (cell == '#') {
      row++;
      continue;
    }

    if (cell == '.' || cell == '/') {
      foundItem = true;
      break;
    }

    int startPass = passes.isEmpty ? 0 : passes.last;
    int passesLeft = maxPasses - (row - startPass);

    List<int> tokens = cell.split('|');
    int total = 0;
    int? itemTotal;

    for (String token in tokens) {
      if (token.isEmpty) continue;

      List<String> parts = token.split(':');
      int count = 0;
      bool valid = true;

      for (String part in parts) {
        if (part.isEmpty) {
          valid = false;
          break;
        }

        List<String> items = part.split(',');
        bool found = false;

        for (String item in items) {
          if (item.isNotEmpty && itemCounts.containsKey(item)) {
            count++;
            found = true;
          }
        }

        if (!found || count < 1) {
          valid = false;
          break;
        }
      }

      if (valid && total + count <= passesLeft) {
        total += count;
        passes.add(total);
        passesLeft -= total;
      }

      if (itemTotal == null) {
        itemTotal = count;
      } else if (itemTotal != count) {
        break;
      }
    }

    if (foundItem) {
      passes.add(total + itemTotal!);
    }

    row++;
  }

  return passes;
}

